    /**
     * Null-preserving, fixed-size list view backed by the source array.
     * Mirrors C# arrays exposed as IList<T>: indexed set writes through to the
     * array, while add/remove remain unsupported.
     */
    public static <T> CSharpGenericIList<T> asListView(T[] items) {
        if (items == null) return null;
        return new ArrayBackedListView<>(items);
    }

    /**
     * Null-preserving, array-backed CSharpGenericIterable view for C# arrays
     * exposed as IEnumerable&lt;T&gt;. Unlike toList(), toArray() returns the
     * SAME array instance, so an array -> IEnumerable -> (T[]) cast round trip
     * preserves reference identity (relied on by e.g. SegWithIndex.Equals).
     */
    public static <T> CSharpGenericIterable<T> asIterable(T[] items) {
        if (items == null) return null;
        return new CSharpArrayIterable<>(items);
    }

    /**
     * A fixed-size list view backed by a Java array.
     * Supports get(), set(), size(), and iteration; structural modifications
     * (add/remove/clear) throw UnsupportedOperationException, matching the
     * C# behavior of arrays exposed as IList&lt;T&gt;.
     */
    private static class ArrayBackedListView<T> extends java.util.AbstractList<T> implements CSharpGenericIList<T> {
        private final T[] array;

        ArrayBackedListView(T[] array) {
            this.array = array;
        }

        @Override
        public T get(int index) {
            return array[index];
        }

        @Override
        public T set(int index, T element) {
            T old = array[index];
            array[index] = element;
            return old;
        }

        @Override
        public int size() {
            return array.length;
        }

        @Override
        public CSharpGenericEnumerator<T> iterator() {
            // Index-based enumerator so reset() restarts the enumeration
            // (C# arrays exposed as IList<T> use List<T>.Enumerator semantics).
            return new CSharpGenericEnumerator<T>() {
                private int index = -1;

                @Override
                public boolean moveNext() {
                    int size = size();
                    if (index >= size) {
                        return false;
                    }
                    index++;
                    return index < size;
                }

                @Override
                public T getCurrent() {
                    if (index < 0 || index >= size()) {
                        throw new IllegalStateException("Enumeration has not started or has already finished.");
                    }
                    return get(index);
                }

                @Override
                public boolean hasNext() {
                    return index + 1 < size();
                }

                @Override
                public T next() {
                    if (!hasNext()) {
                        throw new java.util.NoSuchElementException();
                    }
                    index++;
                    return get(index);
                }

                @Override
                public void reset() {
                    index = -1;
                }

                @Override
                public void remove() {
                    throw new UnsupportedOperationException();
                }
            };
        }

        @Override
        public Object[] toArray() {
            return array;
        }

        @Override
        @SuppressWarnings("unchecked")
        public <E> E[] toArray(E[] a) {
            // Identity-preserving: an empty destination of a compatible component
            // type returns the backing array (C# array -> IList<T> -> (T[]) cast
            // round trips preserve reference identity).
            if (a.length == 0
                    && a.getClass().getComponentType().isAssignableFrom(array.getClass().getComponentType())) {
                return (E[]) array;
            }
            return super.toArray(a);
        }

        @Override
        public void copyTo(T[] dest, int destIndex) {
            for (int i = 0; i < array.length; i++) {
                dest[destIndex + i] = array[i];
            }
        }

        @Override
        public int getCount() {
            return array.length;
        }

        @Override
        public boolean getIsReadOnly() {
            return false;
        }

        @Override
        public void insert(int index, T item) {
            throw new UnsupportedOperationException();
        }

        @Override
        public void removeAt(int index) {
            throw new UnsupportedOperationException();
        }
    }

