    public static <T> T[] copyStructArray(T[] items, IntFunction<T[]> factory, UnaryOperator<T> cloner) {
        if (items == null) return null;
        T[] copy = factory.apply(items.length);
        for (int i = 0; i < items.length; i++) {
            T item = items[i];
            copy[i] = item == null ? null : cloner.apply(item);
        }
        return copy;
    }

