    /** C# Enumerable.Reverse() on an array receiver (the array has no instance methods). */
    public static Object reverseSequence(Object array) {
        int length = java.lang.reflect.Array.getLength(array);
        for (int i = 0; i < length / 2; i++) {
            Object left = java.lang.reflect.Array.get(array, i);
            Object right = java.lang.reflect.Array.get(array, length - 1 - i);
            java.lang.reflect.Array.set(array, i, right);
            java.lang.reflect.Array.set(array, length - 1 - i, left);
        }
        return array;
    }

    /** C# Array.Sort(int[], Comparison&lt;int&gt;) / IComparer&lt;int&gt;. */
    public static void sort(int[] array, java.util.Comparator<Integer> comparator) {
        Integer[] boxed = new Integer[array.length];
        for (int i = 0; i < array.length; i++) boxed[i] = array[i];
        Arrays.sort(boxed, comparator);
        for (int i = 0; i < array.length; i++) array[i] = boxed[i];
    }

    /** Mirrors C# Array.Sort(double[] keys, int[] items): sorts keys ascending, reorders items to match. */
    public static void sortParallel(double[] keys, int[] items) {
        int n = keys.length;
        Integer[] indices = new Integer[n];
        for (int i = 0; i < n; i++) indices[i] = i;
        Arrays.sort(indices, (a, b) -> Double.compare(keys[a], keys[b]));
        double[] sk = new double[n]; int[] sv = new int[n];
        for (int i = 0; i < n; i++) { sk[i] = keys[indices[i]]; sv[i] = items[indices[i]]; }
        System.arraycopy(sk, 0, keys, 0, n); System.arraycopy(sv, 0, items, 0, n);
    }
    /** Mirrors C# Array.Sort(double[] keys, T[] items): sorts keys ascending, reorders items to match. */
    @SuppressWarnings("unchecked")
    public static <T> void sortParallel(double[] keys, T[] items) {
        int n = keys.length;
        Integer[] indices = new Integer[n];
        for (int i = 0; i < n; i++) indices[i] = i;
        Arrays.sort(indices, (a, b) -> Double.compare(keys[a], keys[b]));
        double[] sk = new double[n]; T[] sv = (T[]) new Object[n];
        for (int i = 0; i < n; i++) { sk[i] = keys[indices[i]]; sv[i] = items[indices[i]]; }
        System.arraycopy(sk, 0, keys, 0, n); System.arraycopy(sv, 0, items, 0, n);
    }

    // ---- [B] 元数据 ----

    public static int getLength(Object array) {
        // 调用点可能把数组包成 CSharpArray 写透视图（System.Array 形参归一的
        // 统一形态）；元数据查询必须看裸数组，否则反射抛
        // IllegalArgumentException("Argument is not an array")（真实链
        // dotnet-uri-functional-tests IriEncodingDecodingTest 10 站）。
        if (array instanceof CSharpArray ca) {
            array = ca.unwrap();
        }
        if (array instanceof Object[] arr && arr.length > 0 && arr[0] != null && arr[0].getClass().isArray()) {
            int total = 0;
            for (Object row : arr) {
                total += java.lang.reflect.Array.getLength(row);
            }
            return total;
        }
        return java.lang.reflect.Array.getLength(array);
    }

    public static long getLongLength(Object array) {
        return getLength(array);
    }

    public static int getLength(Object array, int dimension) {
        if (array instanceof CSharpArray ca) {
            array = ca.unwrap();
        }
        if (dimension < 0) throw new IndexOutOfBoundsException();
        Object current = array;
        for (int d = 0; d < dimension; d++) {
            int len = java.lang.reflect.Array.getLength(current);
            if (len == 0) return 0;
            current = java.lang.reflect.Array.get(current, 0);
        }
        return java.lang.reflect.Array.getLength(current);
    }

    public static long getLongLength(Object array, int dimension) {
        return getLength(array, dimension);
    }

    public static int getLowerBound(Object array, int dimension) {
        if (dimension < 0) throw new IndexOutOfBoundsException();
        getLength(array, dimension);
        return 0;
    }

    public static int getUpperBound(Object array, int dimension) {
        return getLowerBound(array, dimension) + getLength(array, dimension) - 1;
    }

